<?php view("community-assets"); ?>
<?php use Namira\{Db,Security,MemberServices};$id=(int)($_GET['edit']??0);$request=$id?MemberServices::request($db,$id,$user):null; ?>
<section class="panel"><h2>درخواست‌های طراحی رایگان</h2><?php foreach(Db::query($db,'SELECT r.*,p.display_name FROM design_requests r LEFT JOIN account_request_owners x ON x.request_id=r.id LEFT JOIN account_profiles p ON p.user_id=x.user_id ORDER BY r.id DESC LIMIT 100')->fetchAll() as $row): ?><p><a href="<?= e(url('admin',['tab'=>'requests','edit'=>$row['id']])) ?>"><?= e($row['martyr_name']) ?></a> · <?= e($row['display_name']??'درخواست قدیمی؛ مالک حساب تطبیق داده نشده') ?> · <?= e($row['status']) ?></p><?php endforeach ?></section>
<?php if($request): ?><article class="panel"><h3><?= e($request['martyr_name']) ?></h3><p><?= e($request['notes']) ?></p><p><?= e($request['requester'].' · '.$request['phone']) ?></p><?php foreach(Db::query($db,'SELECT id FROM request_files WHERE request_id=?',[$id])->fetchAll() as $file): ?><a class="outline" href="<?= e(url('request-file',['id'=>$file['id']])) ?>">پیوست #<?= fa($file['id']) ?></a><?php endforeach ?><form class="community-form" method="post"><?= Security::field() ?><input type="hidden" name="action" value="request-status"><input type="hidden" name="id" value="<?= $id ?>"><label>وضعیت<select name="status"><?php foreach(['submitted'=>'ثبت‌شده','reviewing'=>'در حال بررسی','accepted'=>'پذیرفته‌شده','completed'=>'تکمیل‌شده','rejected'=>'ردشده'] as $s=>$label): ?><option value="<?= $s ?>" <?= $request['status']===$s?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label><button class="primary">ثبت وضعیت</button></form>
<?php foreach(Db::query($db,'SELECT * FROM design_request_messages WHERE request_id=? ORDER BY id',[$id])->fetchAll() as $message): ?><div class="notice"><p><?= e($message['message']) ?></p><small><?= e($message['kind'].' · '.$message['created_at']) ?></small></div><?php endforeach ?>
<form class="community-form" method="post" enctype="multipart/form-data"><?= Security::field() ?><input type="hidden" name="action" value="request-message"><input type="hidden" name="request_id" value="<?= $id ?>"><label>نوع پاسخ<select name="kind"><option value="reply">پاسخ</option><option value="needs_changes">درخواست تکمیل اطلاعات</option><option value="delivery">تحویل نتیجه طراحی</option></select></label><label>پیام قابل مشاهده درخواست‌کننده<textarea name="message" required maxlength="5000" rows="4"></textarea></label><label>فایل تصویری نتیجه یا راهنما؛ اختیاری<input type="file" name="photo" accept=".jpg,.jpeg,.png,.webp"></label><button class="primary">ارسال پیام یا نتیجه</button></form></article><?php endif ?>
